def create_user_directories(user_id):
    backtest_dir_path = os.path.join(BACKTEST_DIR_PATH, user_id)
    os.makedirs(backtest_dir_path, exist_ok=True)
    notebook_dir_path = os.path.join(NOTEBOOK_USER_PATH, user_id)
    os.makedirs(notebook_dir_path, exist_ok=True)
    strategy_dir_path = os.path.join(STRATEGY_DIR_PATH, user_id)
    os.makedirs(strategy_dir_path, exist_ok=True)
    trade_dir_path = os.path.join(TRADE_DIR_PATH, user_id)
    os.makedirs(trade_dir_path, exist_ok=True)
def save_user_info(user_id, **kwargs):
    create_user_directories(user_id)
    user_info = {'pboxuname': user_id}
    for key, value in kwargs.items():
        if not 'pwd' in key:
            if 'password' in key:
                user_info[key] = encrypt(str(value))
            user_info[key] = value
            continue
    else:
        user_info_path = os.path.join(TRADE_DIR_PATH, user_id, 'userinfo.json')
        if not os.path.exists(user_info_path):
            with open(user_info_path, 'w', encoding='utf-8') as fw:
                json.dump(user_info, fw)
        else:
            current_user_info = json.load(open(user_info_path, 'r', encoding='utf-8'))
            with open(user_info_path, 'w', encoding='utf-8') as fw:
                json.dump(current_user_info, fw)
    os.system('sudo chmod -R 777 %s' % user_info_path)
    os.system('sudo chown -R fly:fly %s' % user_info_path)
def get_user_info(user_id=None):
    if user_id is None:
        user_info_path = os.path.join(TRADE_DIR_PATH, 'userinfo.json')
    else:
        user_info_path = os.path.join(TRADE_DIR_PATH, user_id, 'userinfo.json')
    user_info = {}
    if os.path.exists(user_info_path):
        with open(user_info_path, 'r', encoding='utf-8') as fr:
            user_info = json.load(fr)
            for key, value in user_info.items():
                if 'pwd' in key:
                    user_info[key] = decrypt(value)
                continue
    return user_info
def get_docker_python_version(user_id, default_python_version=None):
    match default_python_version:
        case None:
            custom_config = GeneralConf(confPath=os.path.join(FLY_CONFIG_PATH, 'custom_config.conf'), is_reload=True)
            default_python_version = custom_config.getconfigvalue('login_control', 'python_version', 'py35')
    try:
        return get_user_info(user_id).get('python_version', default_python_version)
        return None
    except BaseException:
        system_log.error(f'获取用户{user_id!s}容器的Python版本失败，默认返回：{default_python_version!s}，错误原因：{get_traceback_message()!s}')
        return default_python_version
def get_vip_user_info():
    vip_user_info = dict()
    error_dict, response = do_request(360022, account_type='PTRADE_INTERFACE')
    if error_dict.get('error_no') != 0:
        system_log.error('获取VIP用户列表异常，错误信息：{}'.format(error_dict.get('error_info')))
        return vip_user_info
    else:
        for user_info in response:
            fund_account = user_info.get('fund_account', None)
            if fund_account is not None:
                kwargs = {'fund_account': fund_account}
                account_error_dict, account_response = do_request(*((362613,)), **(kwargs))
                if account_error_dict.get('error_no') != 0:
                    system_log.error('VIP用户{}量化交易权限控制串查询失败，错误信息：{}'.format(fund_account, account_error_dict.get('error_info')))
                    continue
                for account_info in account_response:
                    if 'config_id' in account_info.keys():
                        item_key = int(account_info.get('config_id'))
                        if item_key == 1005:
                            account_config = str(account_info.get('config_value_ter', '0'))
                            if len(account_config) < 2:
                                system_log.error('VIP用户{}量化交易权限控制串{}长度异常'.format(fund_account, account_config))
                                continue
                            vip_user_info[fund_account] = account_config[1]
                        continue
                    item_key = int(account_info.get('config_no', 0))
                    if item_key == 1005:
                        account_config = str(account_info.get('config_info', '0'))
                        if len(account_config) < 2:
                            system_log.error('VIP用户{}量化交易权限控制串{}长度异常'.format(fund_account, account_config))
                            continue
                        vip_user_info[fund_account] = account_config[1]
                    continue
        else:
            return vip_user_info
def remove_lock_files(user_id):
    base_dirs = [os.path.join(BACKTEST_DIR_PATH, user_id), os.path.join(NOTEBOOK_USER_PATH, user_id), os.path.join(STRATEGY_DIR_PATH, user_id), os.path.join(TRADE_DIR_PATH, user_id)]
    for base_dir in base_dirs:
        if os.path.exists(base_dir):
            for root, dirs, files in os.walk(base_dir):
                for file in files:
                    if file.endswith('.lock'):
                        file_path = os.path.join(root, file)
                        try:
                            os.unlink(file_path)
                        except BaseException:
                            system_log.error('用户 {} 锁文件 {} 清理失败，错误原因：{}'.format(user_id, file_path, get_traceback_message()))
                            continue
        continue
async def init_user_env(user_id, python_version=None):
    script_path = os.path.join(WORKSPACE_DIR_PATH, 'init_user_env.pyc')
